function validate(input) {
  const [{ cities = [] }] = input;
  const seen = new Set();
  for (const [state, city] of cities) {
    if (state === null || city === null || state === '' || city === '') return 'state and city must be non-empty.';
    const key = `${String(state).toLowerCase()}|${String(city).toLowerCase()}`;
    if (seen.has(key)) return `${city}, ${state} appears twice.`;
    seen.add(key);
  }
  return null;
}

