function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const cities = [];
  if (size === 'small') {
    const pools = {
      'Texas': ['Tyler', 'Temple', 'Dallas', 'Austin', 'Taylor'],
      'Ohio': ['Oxford', 'Akron', 'Dayton', 'Orrville', 'Toledo'],
      'Maine': ['Machias', 'Bangor', 'Augusta', 'Portland'],
      'New York': ['Newark', 'New York City', 'Buffalo', 'Rochester', 'Albany'],
    };
    const states = Object.keys(pools);
    const target = pick(9);
    const used = new Set();
    for (let tries = 0; tries < 40 && cities.length < target; tries++) {
      // Favour one or two states so groups reach three cities.
      const state = states[pick(rand() < 0.7 ? 2 : states.length)];
      const city = pools[state][pick(pools[state].length)];
      if (used.has(`${state}|${city}`)) continue;
      used.add(`${state}|${city}`);
      cities.push([state, city]);
    }
    return [{ cities }];
  }
  const letters = 'BCDKLMNPRST';
  const endings = ['ora', 'enta', 'ivia', 'ulon', 'ana'];
  for (let i = 0; i < 300 && cities.length < 2000; i++) {
    const initial = letters[pick(letters.length)];
    const state = `${initial}${endings[pick(endings.length)]} ${i}`;
    const count = pick(13);
    for (let j = 0; j < count && cities.length < 2000; j++) {
      const cityInitial = rand() < 0.3 ? initial : letters[pick(letters.length)];
      cities.push([state, `${cityInitial}${endings[pick(endings.length)]}ville ${j}`]);
    }
  }
  return [{ cities }];
}
